<?php
/*
 * Aplica as correcções dos testes (8 ficheiros). Uso, dentro de apps\api:
 *     php aplicar-correcoes.php
 * Escreve cada ficheiro no caminho certo a partir da pasta actual e mostra
 * o caminho completo — assim vê-se exactamente onde ficaram.
 */
if (!file_exists(getcwd() . DIRECTORY_SEPARATOR . 'artisan')) {
    fwrite(STDERR, "ERRO: corra este script dentro de apps\\api (a pasta onde está o ficheiro 'artisan').\nPasta actual: " . getcwd() . "\n");
    exit(1);
}

$files = [
    'app/Http/Controllers/Api/V1/Admin/ContactMessageController.php' => '',
    'app/Http/Requests/Admin/StoreStationRequest.php' => '',
    'tests/Feature/Admin/AdminOrderProvinceScopeTest.php' => '',
    'tests/Feature/Admin/AdminUserProvinceScopeTest.php' => '',
    'tests/Feature/Admin/BillingTest.php' => '',
    'tests/Feature/Driver/DriverRatingStatsExportTest.php' => '',
    'tests/Feature/ExampleTest.php' => '',
    'tests/TestCase.php' => '',
];

foreach ($files as $path => $b64) {
    $target = getcwd() . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $path);
    if (!is_dir(dirname($target))) {
        mkdir(dirname($target), 0777, true);
    }
    file_put_contents($target, base64_decode($b64));
    echo "escrito: $target (" . filesize($target) . " bytes)\n";
}

echo "\nVerificação:\n";
$checks = [
    'tests/TestCase.php' => 'kerugas.sms.provider',
    'tests/Feature/ExampleTest.php' => '/up',
    'tests/Feature/Admin/BillingTest.php' => 'cylinder_types_confirmed',
    'app/Http/Controllers/Api/V1/Admin/ContactMessageController.php' => "latest('id')",
];
foreach ($checks as $path => $needle) {
    $ok = str_contains((string) file_get_contents(getcwd() . '/' . $path), $needle);
    echo ($ok ? 'OK    ' : 'FALHOU') . " $path\n";
}
echo "\nAgora corra: php artisan test\n";
